-- Confere Host - migração MySQL/XAMPP para PostgreSQL/Supabase
-- Execute este arquivo inteiro no SQL Editor do Supabase.

BEGIN;

DROP TABLE IF EXISTS conferencia_itens CASCADE;
DROP TABLE IF EXISTS conferencias CASCADE;
DROP TABLE IF EXISTS produtos CASCADE;
DROP TABLE IF EXISTS login_lojas CASCADE;
DROP TABLE IF EXISTS usuarios CASCADE;
DROP TABLE IF EXISTS lojas CASCADE;

CREATE TABLE lojas (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nome VARCHAR(150) NOT NULL,
  cnpj VARCHAR(20),
  endereco VARCHAR(255),
  ativo SMALLINT NOT NULL DEFAULT 1 CHECK (ativo IN (0,1)),
  criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE usuarios (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nome VARCHAR(150) NOT NULL,
  email VARCHAR(180) NOT NULL UNIQUE,
  senha VARCHAR(255) NOT NULL,
  tipo VARCHAR(20) DEFAULT 'conferente' CHECK (tipo IN ('admin','gerente','conferente')),
  loja_id INTEGER REFERENCES lojas(id),
  ativo SMALLINT NOT NULL DEFAULT 1 CHECK (ativo IN (0,1)),
  criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE login_lojas (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  loja_id INTEGER NOT NULL UNIQUE REFERENCES lojas(id) ON DELETE CASCADE,
  usuario VARCHAR(80) NOT NULL UNIQUE,
  senha_hash VARCHAR(255) NOT NULL,
  ativo SMALLINT NOT NULL DEFAULT 1 CHECK (ativo IN (0,1)),
  criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  atualizado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE produtos (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  codigo VARCHAR(50) NOT NULL,
  codigo_barras VARCHAR(100),
  descricao VARCHAR(255) NOT NULL,
  unidade VARCHAR(20),
  margem NUMERIC(10,2) DEFAULT 0,
  estoque NUMERIC(12,3) DEFAULT 0,
  custo NUMERIC(12,2) DEFAULT 0,
  preco NUMERIC(12,2) DEFAULT 0,
  fator NUMERIC(12,3),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  loja_id INTEGER NOT NULL REFERENCES lojas(id),
  CONSTRAINT uq_produtos_loja_codigo UNIQUE (loja_id, codigo)
);

CREATE TABLE conferencias (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  loja_id INTEGER NOT NULL REFERENCES lojas(id),
  usuario_id INTEGER REFERENCES usuarios(id),
  numero_nota VARCHAR(60),
  fornecedor VARCHAR(180),
  data_nota DATE,
  total_itens INTEGER DEFAULT 0,
  total_erros INTEGER DEFAULT 0,
  valor_total NUMERIC(14,2) DEFAULT 0,
  status VARCHAR(20) CHECK (status IN ('finalizada','com_erro')),
  criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE conferencia_itens (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  conferencia_id INTEGER NOT NULL REFERENCES conferencias(id) ON DELETE CASCADE,
  codigo VARCHAR(100),
  descricao VARCHAR(255),
  unidade VARCHAR(20),
  quantidade NUMERIC(12,3),
  fator NUMERIC(12,3),
  volumes NUMERIC(12,3),
  status VARCHAR(50),
  observacao TEXT
);

CREATE INDEX idx_produtos_loja ON produtos(loja_id);
CREATE INDEX idx_produtos_descricao ON produtos(loja_id, descricao);
CREATE INDEX idx_conferencias_loja_data ON conferencias(loja_id, criado_em DESC);
CREATE INDEX idx_conferencia_itens_conferencia ON conferencia_itens(conferencia_id);

CREATE OR REPLACE FUNCTION atualizar_timestamp()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER produtos_atualizar_timestamp
BEFORE UPDATE ON produtos
FOR EACH ROW EXECUTE FUNCTION atualizar_timestamp();


