SELECT setval(pg_get_serial_sequence('usuarios','id'), COALESCE((SELECT MAX(id) FROM usuarios), 1), true);
SELECT setval(pg_get_serial_sequence('login_lojas','id'), COALESCE((SELECT MAX(id) FROM login_lojas), 1), true);
SELECT setval(pg_get_serial_sequence('produtos','id'), COALESCE((SELECT MAX(id) FROM produtos), 1), true);
SELECT setval(pg_get_serial_sequence('conferencias','id'), COALESCE((SELECT MAX(id) FROM conferencias), 1), true);
SELECT setval(pg_get_serial_sequence('conferencia_itens','id'), COALESCE((SELECT MAX(id) FROM conferencia_itens), 1), true);

