-- Conferência rápida
SELECT 'lojas' AS tabela, COUNT(*) AS registros FROM lojas
UNION ALL SELECT 'login_lojas', COUNT(*) FROM login_lojas
UNION ALL SELECT 'produtos', COUNT(*) FROM produtos
UNION ALL SELECT 'conferencias', COUNT(*) FROM conferencias
UNION ALL SELECT 'conferencia_itens', COUNT(*) FROM conferencia_itens;
